<?php /** @var array $packages @var bool $saved @var \Core\Security\Csrf $csrf */ ?>
<?php if ($saved): ?><div class="flash-ok">Package changes saved.</div><?php endif; ?>
<div class="card"><h2 style="margin-top:0">Packages</h2><div style="overflow:auto"><table><thead><tr><th>Name</th><th>Starting price</th><th>Guests</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($packages as $package): ?><tr><td><?= e($package['name']) ?></td><td>$<?= e(number_format(((int) $package['price_cents']) / 100, 2)) ?></td><td><?= (int) $package['guest_min'] ?><?= $package['guest_max'] ? '–' . (int) $package['guest_max'] : '+' ?></td><td><?= $package['visible'] ? 'Visible' : 'Hidden' ?></td><td><form method="post" style="display:inline"><?= $csrf->field() ?><input type="hidden" name="action" value="toggle_package"><input type="hidden" name="id" value="<?= (int) $package['id'] ?>"><button class="btn small secondary"><?= $package['visible'] ? 'Hide' : 'Show' ?></button></form> <form method="post" style="display:inline"><?= $csrf->field() ?><input type="hidden" name="action" value="delete_package"><input type="hidden" name="id" value="<?= (int) $package['id'] ?>"><button class="btn small danger" onclick="return confirm('Remove this package?')">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="card"><h2 style="margin-top:0">Add package</h2><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="add_package"><label>Name<input name="name" required maxlength="190"></label><label>Short label<input name="eyebrow" placeholder="Our most popular" maxlength="120"></label><label>Description<textarea name="description" rows="4" maxlength="3000"></textarea></label><label>Starting price<input type="number" name="price" min="0" step="0.01"></label><label>Price note<input name="price_note" value="starting per guest" maxlength="120"></label><label>Minimum guests<input type="number" name="guest_min" min="1" value="20"></label><label>Maximum guests <span class="muted">leave blank for no maximum</span><input type="number" name="guest_max" min="1"></label><label>Inclusions <span class="muted">one per line</span><textarea name="inclusions" rows="8" maxlength="5000"></textarea></label><label><input type="checkbox" name="featured" value="1" style="width:auto"> Mark as most popular</label><label>Sort order<input type="number" name="sort_order" value="50"></label><button class="btn" type="submit">Add package</button></form></div>
